1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Agent Directory — Polyglot</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
9	<style>
10	:root {
11	  --bg:#F8F7F4;--bg2:#FFFFFF;--bg3:#F1EFE8;
12	  --tx:#1A1A18;--tx2:#6B6A65;--tx3:#9C9B96;
13	  --bd:rgba(0,0,0,0.08);--bd2:rgba(0,0,0,0.14);
14	  --accent:#2D5BE3;--accent-bg:#EBF0FD;--accent-tx:#1E3FA0;
15	  --green:#0F6E56;--green-bg:#E1F5EE;
16	  --amber:#854F0B;--amber-bg:#FAEEDA;
17	  --red:#A32D2D;--red-bg:#FCEBEB;
18	  --purple:#534AB7;--purple-bg:#EEEDFE;
19	  --coral:#993C1D;--coral-bg:#FAECE7;
20	  --sans:'DM Sans',-apple-system,sans-serif;
21	  --mono:'JetBrains Mono',monospace;
22	  --radius:10px;--radius-lg:14px;
23	  --tag-tech-bg:#EBF0FD;--tag-tech-tx:#1E3FA0;
24	  --tag-dom-bg:#E1F5EE;--tag-dom-tx:#0F6E56;
25	  --tag-wt-bg:#EEEDFE;--tag-wt-tx:#534AB7;
26	}
27	@media(prefers-color-scheme:dark){:root{
28	  --bg:#161615;--bg2:#1E1E1C;--bg3:#262624;
29	  --tx:#E8E6DE;--tx2:#9C9B96;--tx3:#6B6A65;
30	  --bd:rgba(255,255,255,0.08);--bd2:rgba(255,255,255,0.14);
31	  --accent:#6B8EF0;--accent-bg:#1E2A4A;--accent-tx:#A3BBF7;
32	  --green:#5DCAA5;--green-bg:#0A3028;
33	  --amber:#EF9F27;--amber-bg:#2E2008;
34	  --red:#F09595;--red-bg:#301515;
35	  --purple:#AFA9EC;--purple-bg:#1E1C38;
36	  --coral:#F0997B;--coral-bg:#2A1510;
37	  --tag-tech-bg:#1E2A4A;--tag-tech-tx:#A3BBF7;
38	  --tag-dom-bg:#0A3028;--tag-dom-tx:#5DCAA5;
39	  --tag-wt-bg:#1E1C38;--tag-wt-tx:#AFA9EC;
40	}}
41	*{box-sizing:border-box;margin:0;padding:0}
42	body{font-family:var(--sans);background:var(--bg);color:var(--tx);min-height:100vh;display:flex;overflow:hidden;height:100vh}
43	
44	/* ── Sidebar ── */
45	.sidebar{width:256px;min-width:256px;background:var(--bg2);border-right:1px solid var(--bd);display:flex;flex-direction:column;height:100vh;overflow:hidden}
46	.sb-top{padding:16px 16px 12px;border-bottom:1px solid var(--bd);flex-shrink:0}
47	.sb-logo{display:flex;align-items:center;gap:8px;font-size:15px;font-weight:600;letter-spacing:-.3px;margin-bottom:10px}
48	.sb-logo-icon{width:26px;height:26px;background:var(--accent);border-radius:7px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:700}
49	.sb-count{font-size:11px;color:var(--tx3)}
50	.sb-search{width:100%;padding:7px 11px;border:1px solid var(--bd);border-radius:8px;font-family:var(--sans);font-size:13px;background:var(--bg3);color:var(--tx);outline:none;margin-top:10px}
51	.sb-search:focus{border-color:var(--accent);background:var(--bg2)}
52	.sb-body{flex:1;overflow-y:auto;padding:6px 0}
53	.sb-sec-head{padding:6px 14px 2px;font-size:10px;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--tx3);margin-top:4px}
54	.sb-item{display:flex;align-items:center;gap:7px;padding:4px 14px;cursor:pointer;font-size:12px;color:var(--tx2);transition:background .1s}
55	.sb-item:hover{background:var(--bg3)}
56	.sb-item input{cursor:pointer;accent-color:var(--accent);flex-shrink:0}
57	.sb-item .fi-label{flex:1}
58	.fi-count{font-size:11px;color:var(--tx3);background:var(--bg3);border-radius:8px;padding:1px 6px;font-weight:500}
59	.sb-item.active .fi-count{background:var(--accent);color:#fff}
60	.sb-sep{height:1px;background:var(--bd);margin:5px 14px}
61	.sb-footer{padding:12px 14px;border-top:1px solid var(--bd);flex-shrink:0}
62	.clear-btn{width:100%;padding:7px;border-radius:8px;border:1px solid var(--bd);background:var(--bg);color:var(--tx2);font-size:12px;font-weight:500;cursor:pointer;font-family:var(--sans);transition:all .15s}
63	.clear-btn:hover{background:var(--red-bg);color:var(--red);border-color:transparent}
64	
65	/* ── Main ── */
66	.main{flex:1;min-width:0;display:flex;flex-direction:column;height:100vh;overflow:hidden}
67	.main-hdr{padding:13px 22px 11px;border-bottom:1px solid var(--bd);background:var(--bg2);flex-shrink:0}
68	.hdr-row1{display:flex;align-items:center;gap:10px}
69	.main-title{font-size:16px;font-weight:600;letter-spacing:-.3px}
70	.view-tgl{display:flex;gap:3px;margin-left:auto}
71	.vbtn{padding:5px 11px;border-radius:7px;border:1px solid var(--bd);background:var(--bg);color:var(--tx2);font-size:12px;font-weight:500;cursor:pointer;font-family:var(--sans);transition:all .15s}
72	.vbtn:hover{background:var(--bg3);color:var(--tx)}
73	.vbtn.active{background:var(--accent);color:#fff;border-color:var(--accent)}
74	.chips-row{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px;min-height:0}
75	.chips-row:empty{margin-top:0}
76	.chip{display:inline-flex;align-items:center;gap:4px;padding:2px 8px 2px 10px;border-radius:20px;font-size:11px;font-weight:500;cursor:pointer;transition:opacity .15s}
77	.chip:hover{opacity:.7}
78	.chip.tech{background:var(--tag-tech-bg);color:var(--tag-tech-tx)}
79	.chip.domain{background:var(--tag-dom-bg);color:var(--tag-dom-tx)}
80	.chip.wt{background:var(--tag-wt-bg);color:var(--tag-wt-tx)}
81	.chip.dept{background:var(--bg3);color:var(--tx2)}
82	.chip-x{font-size:13px;line-height:1}
83	.main-body{flex:1;overflow-y:auto;padding:18px 22px}
84	.result-bar{font-size:12px;color:var(--tx3);margin-bottom:12px}
85	
86	/* ── Grid ── */
87	.grid-view{display:grid;grid-template-columns:repeat(auto-fill,minmax(272px,1fr));gap:10px}
88	.acard{background:var(--bg2);border:1px solid var(--bd);border-radius:var(--radius-lg);padding:15px;cursor:pointer;transition:border-color .15s,box-shadow .15s}
89	.acard:hover{border-color:var(--accent);box-shadow:0 2px 12px rgba(45,91,227,.09)}
90	.ac-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:5px}
91	.ac-name{font-size:13px;font-weight:600;letter-spacing:-.2px;line-height:1.3}
92	.ac-badges{display:flex;gap:3px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end}
93	.badge{display:inline-flex;align-items:center;padding:2px 6px;border-radius:5px;font-size:10px;font-weight:600}
94	.b-opus{background:var(--amber-bg);color:var(--amber)}
95	.b-sonnet{background:var(--accent-bg);color:var(--accent-tx)}
96	.b-haiku{background:var(--bg3);color:var(--tx3)}
97	.b-level{background:var(--bg3);color:var(--tx2)}
98	.ac-role{font-size:11px;color:var(--tx2);margin-bottom:7px}
99	.ac-desc{font-size:12px;color:var(--tx2);line-height:1.5;margin-bottom:9px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
100	.tag-row{display:flex;flex-wrap:wrap;gap:3px;margin-bottom:3px}
101	.t{display:inline-flex;padding:2px 7px;border-radius:5px;font-size:10px;font-weight:500;cursor:pointer;transition:opacity .15s}
102	.t:hover{opacity:.7}
103	.t.tech{background:var(--tag-tech-bg);color:var(--tag-tech-tx)}
104	.t.domain{background:var(--tag-dom-bg);color:var(--tag-dom-tx)}
105	.t.wt{background:var(--tag-wt-bg);color:var(--tag-wt-tx)}
106	.ac-foot{display:flex;align-items:center;justify-content:space-between;margin-top:9px;padding-top:9px;border-top:1px solid var(--bd)}
107	.dept-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}
108	.ac-reports{font-size:11px;color:var(--tx3)}
109	
110	/* ── List ── */
111	.list-wrap{overflow-x:auto}
112	table.lv{width:100%;border-collapse:collapse}
113	table.lv th{text-align:left;padding:7px 10px;font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;color:var(--tx3);border-bottom:1px solid var(--bd);cursor:pointer;white-space:nowrap;user-select:none}
114	table.lv th:hover{color:var(--tx2)}
115	table.lv td{padding:9px 10px;border-bottom:1px solid var(--bd);font-size:12px;vertical-align:middle}
116	table.lv tr:hover td{background:var(--bg3);cursor:pointer}
117	table.lv tr:last-child td{border-bottom:none}
118	.lv-name{font-weight:600;display:flex;align-items:center;gap:5px}
119	.lv-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}
120	.lv-tags{display:flex;flex-wrap:wrap;gap:3px}
121	
122	/* ── Grouped ── */
123	.sg{margin-bottom:26px}
124	.sg-head{display:flex;align-items:center;gap:9px;margin-bottom:11px;padding-bottom:7px;border-bottom:2px solid var(--bd)}
125	.sg-dot{width:10px;height:10px;border-radius:50%;flex-shrink:0}
126	.sg-title{font-size:14px;font-weight:600;letter-spacing:-.2px}
127	.sg-cnt{font-size:11px;color:var(--tx3);background:var(--bg3);padding:2px 8px;border-radius:10px;font-weight:500}
128	.sg-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(272px,1fr));gap:9px}
129	.sg-filter{margin-left:auto;cursor:pointer}
130	
131	/* ── Slide-out Panel ── */
132	.p-overlay{position:fixed;inset:0;background:rgba(0,0,0,0);z-index:50;pointer-events:none;transition:background .2s}
133	.p-overlay.open{background:rgba(0,0,0,.32);pointer-events:all}
134	.panel{position:absolute;right:-450px;top:0;bottom:0;width:430px;background:var(--bg2);border-left:1px solid var(--bd);overflow-y:auto;transition:right .25s cubic-bezier(.4,0,.2,1)}
135	.p-overlay.open .panel{right:0}
136	.p-hdr{padding:15px 18px 13px;border-bottom:1px solid var(--bd);position:sticky;top:0;background:var(--bg2);z-index:1}
137	.p-name{font-size:17px;font-weight:600;letter-spacing:-.3px;margin-bottom:2px;padding-right:32px}
138	.p-title{font-size:12px;color:var(--tx2)}
139	.p-close{position:absolute;right:14px;top:14px;width:27px;height:27px;border-radius:7px;border:1px solid var(--bd);background:var(--bg);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;color:var(--tx2);transition:all .15s}
140	.p-close:hover{background:var(--bg3);color:var(--tx)}
141	.p-body{padding:15px 18px}
142	.p-sec{margin-bottom:16px}
143	.p-sec-title{font-size:10px;font-weight:600;letter-spacing:.07em;text-transform:uppercase;color:var(--tx3);margin-bottom:7px}
144	.p-desc{font-size:12px;color:var(--tx2);line-height:1.6}
145	.p-meta{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--tx2);margin-bottom:4px}
146	.p-ml{color:var(--tx3);width:88px;flex-shrink:0;font-size:11px}
147	.p-tag-row{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:4px}
148	.rel-strip{display:flex;flex-wrap:wrap;gap:5px}
149	.rel-chip{padding:3px 9px;border-radius:7px;border:1px solid var(--bd);font-size:11px;cursor:pointer;background:var(--bg3);color:var(--tx2);transition:all .15s}
150	.rel-chip:hover{border-color:var(--accent);color:var(--accent-tx)}
151	.skill-row{display:flex;align-items:center;gap:7px;margin-bottom:5px}
152	.skill-lbl{font-size:11px;color:var(--tx2);width:88px;flex-shrink:0}
153	.skill-bg{flex:1;height:4px;background:var(--bg3);border-radius:2px;overflow:hidden}
154	.skill-fill{height:100%;background:var(--accent);border-radius:2px;transition:width .4s}
155	.skill-pct{font-size:10px;color:var(--tx3);width:28px;text-align:right;flex-shrink:0}
156	
157	/* ── Utils ── */
158	.empty{text-align:center;padding:50px 20px;color:var(--tx3);grid-column:1/-1}
159	.empty-icon{font-size:36px;margin-bottom:10px}
160	.empty-title{font-size:14px;font-weight:500;color:var(--tx2);margin-bottom:4px}
161	.loading{text-align:center;padding:40px;color:var(--tx3);font-size:14px}
162	</style>
163	</head>
164	<body>
165	
166	<aside class="sidebar">
167	  <div class="sb-top">
168	    <div class="sb-logo">
169	      <div class="sb-logo-icon">P</div>
170	      Agent Directory
171	    </div>
172	    <div class="sb-count" id="sbCount">Loading…</div>
173	    <input class="sb-search" id="searchInput" placeholder="Search name, role, tech…" autocomplete="off">
174	  </div>
175	  <div class="sb-body" id="sbBody"></div>
176	  <div class="sb-footer">
177	    <button class="clear-btn" onclick="clearAll()">Clear all filters</button>
178	  </div>
179	</aside>
180	
181	<div class="main">
182	  <div class="main-hdr">
183	    <div class="hdr-row1">
184	      <div class="main-title">Agents</div>
185	      <div class="view-tgl">
186	        <button class="vbtn active" id="v-grid" onclick="setView('grid')">Grid</button>
187	        <button class="vbtn" id="v-list" onclick="setView('list')">List</button>
188	        <button class="vbtn" id="v-dept" onclick="setView('dept')">Department</button>
189	        <button class="vbtn" id="v-tech" onclick="setView('tech')">Tech Stack</button>
190	      </div>
191	    </div>
192	    <div class="chips-row" id="chipsRow"></div>
193	  </div>
194	  <div class="main-body">
195	    <div class="result-bar" id="resultBar"></div>
196	    <div id="content"><div class="loading">Loading agents…</div></div>
197	  </div>
198	</div>
199	
200	<div class="p-overlay" id="pOverlay" onclick="handleOvClick(event)">
201	  <div class="panel" id="panel">
202	    <div class="p-hdr">
203	      <div class="p-name" id="pName"></div>
204	      <div class="p-title" id="pTitle"></div>
205	      <div class="p-close" onclick="closePanel()">✕</div>
206	    </div>
207	    <div class="p-body" id="pBody"></div>
208	  </div>
209	</div>
210	
211	<script>
212	const API = 'http://localhost:3847/api';
213	const DEPT_COLORS = {executive:'#a855f7',engineering:'#3b82f6',design:'#ec4899','content-seo':'#f97316',growth:'#10b981',research:'#06b6d4',hr:'#eab308',creative:'#9ca3af'};
214	const DEPT_ORDER = ['executive','engineering','design','content-seo','growth','research','hr'];
215	const TAXONOMY = {
216	  tech:{label:'Technology',cls:'tech',tags:['shopify','nextjs','supabase','react','typescript','railway','figma','playwright','tailwind','polaris','hydrogen','postgresql','shadcn','postmark','sentry','posthog']},
217	  domain:{label:'Domain',cls:'domain',tags:['ecommerce','saas','design-system','devops','data','seo','conversion','market-research','portfolio','hr-ops','brand']},
218	  'work-type':{label:'Work Type',cls:'wt',tags:['design','coding','testing','copywriting','email','strategy','research','review','deploy','training','monitoring']}
219	};
220	
221	let allAgents=[], depts={}, filters={tech:[],domain:[],'work-type':[],department:null,q:''};
222	let view='grid', sortCol='name', sortDir=1;
223	
224	async function init(){
225	  try{
226	    const[ad,dd]=await Promise.all([fetch(`${API}/agents/directory?limit=200`),fetch(`${API}/departments`)]);
227	    const agData=await ad.json(), dData=await dd.json();
228	    allAgents=agData.agents||[];
229	    (dData.departments||[]).forEach(d=>{depts[d.id]=d});
230	    renderSidebar(); renderAll();
231	  }catch(e){
232	    document.getElementById('content').innerHTML=`<div class="empty"><div class="empty-icon">⚠️</div><div class="empty-title">Server offline</div><div>Start Polyglot at localhost:3847</div></div>`;
233	    document.getElementById('sbCount').textContent='Server offline';
234	  }
235	}
236	
237	function filtered(){
238	  return allAgents.filter(a=>{
239	    const tg=a.tags||{};
240	    for(const cat of['tech','domain','work-type']){
241	      const sel=filters[cat];
242	      if(!sel||!sel.length)continue;
243	      if(!sel.some(v=>(tg[cat]||[]).includes(v)))return false;
244	    }
245	    if(filters.department&&a.department!==filters.department)return false;
246	    if(filters.q){
247	      const q=filters.q.toLowerCase();
248	      if(!(a.name||'').toLowerCase().includes(q)&&!(a.title||'').toLowerCase().includes(q)&&!(a.description||'').toLowerCase().includes(q)&&!a.id.toLowerCase().includes(q))return false;
249	    }
250	    return true;
251	  });
252	}
253	
254	function countTag(cat,val){
255	  return allAgents.filter(a=>{
256	    const tg=a.tags||{};
257	    for(const c of['tech','domain','work-type']){
258	      const sel=c===cat?[val]:filters[c];
259	      if(!sel||!sel.length)continue;
260	      if(!sel.some(v=>(tg[c]||[]).includes(v)))return false;
261	    }
262	    if(filters.department&&a.department!==filters.department)return false;
263	    return true;
264	  }).length;
265	}
266	
267	function renderSidebar(){
268	  let html='';
269	  for(const[ck,cat]of Object.entries(TAXONOMY)){
270	    html+=`<div><div class="sb-sec-head">${cat.label}</div>`;
271	    for(const tv of cat.tags){
272	      const checked=filters[ck].includes(tv);
273	      const cnt=countTag(ck,tv);
274	      if(!cnt&&!checked)continue;
275	      html+=`<label class="sb-item${checked?' active':''}"><input type="checkbox"${checked?' checked':''} onchange="togTag('${ck}','${tv}',this.checked)"><span class="fi-label">${tv}</span><span class="fi-count">${cnt}</span></label>`;
276	    }
277	    html+=`</div><div class="sb-sep"></div>`;
278	  }
279	  html+=`<div><div class="sb-sec-head">Department</div>`;
280	  for(const id of DEPT_ORDER){
281	    const d=depts[id]||{id,label:id,color:'#9ca3af'};
282	    const cnt=allAgents.filter(a=>a.department===id&&['tech','domain','work-type'].every(c=>!filters[c].length||filters[c].some(v=>(a.tags?.[c]||[]).includes(v)))).length;
283	    if(!cnt)continue;
284	    const active=filters.department===id;
285	    html+=`<label class="sb-item${active?' active':''}"><input type="checkbox"${active?' checked':''} onchange="togDept('${id}',this.checked)"><span class="fi-label" style="display:flex;align-items:center;gap:6px"><span style="width:7px;height:7px;border-radius:50%;background:${d.color};flex-shrink:0"></span>${d.label||id}</span><span class="fi-count">${cnt}</span></label>`;
286	  }
287	  html+=`</div>`;
288	  document.getElementById('sbBody').innerHTML=html;
289	}
290	
291	function renderAll(){
292	  const f=filtered();
293	  document.getElementById('sbCount').textContent=`${allAgents.length} agents total`;
294	  document.getElementById('resultBar').textContent=`Showing ${f.length} of ${allAgents.length} agents`;
295	  renderChips();
296	  if(view==='grid')renderGrid(f);
297	  else if(view==='list')renderList(f);
298	  else if(view==='dept')renderByDept(f);
299	  else renderByTech(f);
300	}
301	
302	function renderChips(){
303	  let html='';
304	  for(const[cat,vals]of Object.entries({tech:filters.tech,domain:filters.domain,'work-type':filters['work-type']})){
305	    const cls=cat==='tech'?'tech':cat==='domain'?'domain':'wt';
306	    for(const v of vals)html+=`<span class="chip ${cls}" onclick="togTag('${cat}','${v}',false)">${v}<span class="chip-x">✕</span></span>`;
307	  }
308	  if(filters.department)html+=`<span class="chip dept" onclick="togDept('${filters.department}',false)">${filters.department}<span class="chip-x">✕</span></span>`;
309	  document.getElementById('chipsRow').innerHTML=html;
310	}
311	
312	function card(a){
313	  const tg=a.tags||{};
314	  const tech=(tg.tech||[]).slice(0,4);const techMore=(tg.tech||[]).length-tech.length;
315	  const dom=(tg.domain||[]).slice(0,2);const wt=(tg['work-type']||[]).slice(0,2);
316	  const dc=DEPT_COLORS[a.department]||'#9ca3af';
317	  const mc=a.model==='opus'?'b-opus':a.model==='haiku'?'b-haiku':'b-sonnet';
318	  return `<div class="acard" onclick="openPanel('${a.id}')">
319	    <div class="ac-top">
320	      <div class="ac-name">${esc(a.name||a.id)}</div>
321	      <div class="ac-badges">
322	        <span class="badge ${mc}">${a.model||'sonnet'}</span>
323	        ${a.levelTitle?`<span class="badge b-level">${a.levelTitle}</span>`:''}
