346	  const srt=[...agents].sort((a,b)=>{let va=a[sortCol]||a.id,vb=b[sortCol]||b.id;return va<vb?-sortDir:va>vb?sortDir:0});
347	  const th=(c,l)=>`<th onclick="doSort('${c}')">${l}${sortCol===c?(sortDir>0?' ↑':' ↓'):''}</th>`;
